INSERT INTO p_studio_batch (id, act_id, num, br_batch_id, name, brief_json, setup_json, plan_json, status) VALUES ('98d6ab10d32e7a8ea94e19b3', 'brand_bonk_golf', NULL, NULL, 'Early Black Friday: offer-free statics (real photos only)', '{"angle": "Early Black Friday, offer-free lines: gift-giver and product heroes that run before and alongside the warm-up offer.", "why": "235 B (gift-giver line on a plain studio hero) is the account anchor at 1.57x TW, 280 orders in 60 days; in BFCM 2025 the evergreen heroes beat every offer ad.", "concept": "Real bonkgolf.com studio photos only (Floyd: no AI imagery, ever). Every line already has its finished image. Offer lines 12 to 15 wait for Floyd.", "post_copy": "The golf hat with the ball marker and tees built in. Magnet in the bill, tee slots in the side, matching marker in the box.", "testing": "concepts", "lines": [{"text": "ebf-01: Retire his old cap. Gift-giver line from 235 B (the account anchor) on a fresh Dunes Day studio hero. Testing: the winning line in gift season.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/c4b86d792b30a079190c103d.png"}, {"text": "ebf-02: Skip the golf-themed gift. Get the hat he''ll wear every round. Smoke Show hero. Testing: usefulness vs nostalgia (01).", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/4dc6d71ed73b733724859204.png"}, {"text": "ebf-03: Built in. Not bolted on. Twilight + 3 callouts (magnet holds marker, tee slots, matching marker in the box). Testing: callouts vs single line.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/bd45aff83eb011bc2a85fa1c.png"}, {"text": "ebf-04: Review over product: \"My husband loved how his tees have a place other than his ears.\" (Judge.me 5 stars, Pin Raider).", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/7a276d7071580d024a8f61b2.png"}, {"text": "ebf-05: Review over product: \"Man coolest golf hat ever made!\" (Judge.me 5 stars, Viper). Testing: style proof vs function proof (04).", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/97fdf7f3dcb841fb27a56cde.png"}, {"text": "ebf-06: Stop fumbling. Start playing. (225 B line, self-buyer) on Smoke Show three-quarter hero.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/1210cae5a1a979b057c08a6e.png"}, {"text": "ebf-07: Black goes with every bag. Twilight, Viper, Pin Raider three-up. Testing: three blacks vs one hero.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/2df1e2a582d95fa0a65a8396.png"}, {"text": "ebf-08: Built for lefties. Finally. Southpaw Snapback photo only. Testing: lefty audience.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/0b9aaa89ebac0c8da0fb91c3.png"}, {"text": "ebf-09: Review over product: ponytail through 1 of 3 locations (Judge.me 5 stars, Clean Open Back). Testing: women.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/f45f740d164d4b5356df807a.png"}, {"text": "ebf-10: YOUTH SIZE. Make the junior golfer feel legit. Youth Smoke Show. Testing: youth gifter; says youth big because Youth vs Standard is the top refund.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/3abfbadb88422faf9bf80ee0.png"}, {"text": "ebf-11: HOLD until Floyd confirms list-first: New holiday bundles. The list sees them first. Join the list. Smoke Show gift set photo, no price.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/b93ad0cb5ac1df40d533355a.png"}], "source": "Bonk BFCM ads chat, 2026-10-13 (docs/bfcm-bonk-concepts.md, Batch 1 lines 1 to 11)", "reference": "docs/bfcm-bonk-concepts.md"}', '{"products": [], "images": ["https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/c4b86d792b30a079190c103d.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/4dc6d71ed73b733724859204.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/bd45aff83eb011bc2a85fa1c.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/7a276d7071580d024a8f61b2.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/97fdf7f3dcb841fb27a56cde.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/1210cae5a1a979b057c08a6e.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/2df1e2a582d95fa0a65a8396.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/0b9aaa89ebac0c8da0fb91c3.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/f45f740d164d4b5356df807a.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/3abfbadb88422faf9bf80ee0.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/b93ad0cb5ac1df40d533355a.png"], "swipe": []}', NULL, 'draft');
